func (a *Analyzer) resolveType(typeName string) types.Type {
    if typeName == "" {
        return a.scopes.TypeRegistry().Get("Any")
    }
    t := a.scopes.TypeRegistry().Get(typeName)
    if t == nil {
        t = a.scopes.TypeRegistry().Get("Any")
