   443→/* 논리 OR (||) */
   444→Node *parse_logical_or_expr(Parser *p) {
   445→    Node *left = parse_logical_and_expr(p);
   446→
   447→    while (check(p, TK_OR)) {
   448→        Token op_tok = *current_token(p);
   449→        advance(p);
   450→        Node *right = parse_logical_and_expr(p);
   451→
   452→        Node *binary = node_new(ND_BINARY, op_tok.loc);
   453→        binary->left = left;
   454→        binary->right = right;
   455→        binary->op = TK_OR;
   456→        left = binary;
   457→    }
   458→
   459→    return left;
   460→}
   461→
   462→/* 논리 AND (&&) */
   463→Node *parse_logical_and_expr(Parser *p) {
   464→    Node *left = parse_bitwise_or_expr(p);
   465→
   466→    while (check(p, TK_AND)) {
   467→        Token op_tok = *current_token(p);
   468→        advance(p);
   469→        Node *right = parse_bitwise_or_expr(p);
   470→
   471→        Node *binary = node_new(ND_BINARY, op_tok.loc);
   472→        binary->left = left;
   473→        binary->right = right;
   474→        binary->op = TK_AND;
   475→        left = binary;
   476→    }
   477→
   478→    return left;
   479→}
   480→
   481→/* 비트 OR (|) */
   482→Node *parse_bitwise_or_expr(Parser *p) {
   483→    Node *left = parse_bitwise_xor_expr(p);
   484→
   485→    while (check(p, TK_PIPE)) {
   486→        Token op_tok = *current_token(p);
   487→        advance(p);
   488→        Node *right = parse_bitwise_xor_expr(p);
   489→
   490→        Node *binary = node_new(ND_BINARY, op_tok.loc);
   491→        binary->left = left;
   492→        binary->right = right;
   493→        binary->op = TK_PIPE;
   494→        left = binary;
   495→    }
   496→
   497→    return left;
   498→}
   499→
   500→/* 비트 XOR (^) */
   501→Node *parse_bitwise_xor_expr(Parser *p) {
   502→    Node *left = parse_bitwise_and_expr(p);
   503→
   504→    while (check(p, TK_CARET)) {
   505→        Token op_tok = *current_token(p);
   506→        advance(p);
   507→        Node *right = parse_bitwise_and_expr(p);
   508→
   509→        Node *binary = node_new(ND_BINARY, op_tok.loc);
   510→        binary->left = left;
   511→        binary->right = right;
   512→        binary->op = TK_CARET;
   513→        left = binary;
   514→    }
   515→
   516→    return left;
   517→}
   518→
   519→/* 비트 AND (&) */
   520→Node *parse_bitwise_and_expr(Parser *p) {
   521→    Node *left = parse_equality_expr(p);
   522→
   523→    while (check(p, TK_AMPERSAND)) {
   524→        Token op_tok = *current_token(p);
   525→        advance(p);
