   615→/* 곱셈/나눗셈/나머지 (*, /, %) */
   616→Node *parse_multiplicative_expr(Parser *p) {
   617→    Node *left = parse_unary_expr(p);
   618→
   619→    while (check(p, TK_STAR) || check(p, TK_SLASH) || check(p, TK_PERCENT)) {
   620→        Token op_tok = *current_token(p);
   621→        advance(p);
   622→        Node *right = parse_unary_expr(p);
   623→
   624→        Node *binary = node_new(ND_BINARY, op_tok.loc);
   625→        binary->left = left;
   626→        binary->right = right;
   627→        binary->op = op_tok.kind;
   628→        left = binary;
   629→    }
   630→
   631→    return left;
   632→}
   633→
   634→/* 단항 연산자 (-, !, ~, &, *, ++, --) */
   635→Node *parse_unary_expr(Parser *p) {
   636→    Token tok = *current_token(p);
   637→
   638→    if (check(p, TK_MINUS) || check(p, TK_PLUS) || check(p, TK_BANG) ||
   639→        check(p, TK_TILDE) || check(p, TK_AMPERSAND) || check(p, TK_STAR)) {
   640→        TokenKind op = tok.kind;
   641→        advance(p);
   642→        Node *expr = parse_unary_expr(p);
   643→
   644→        Node *unary = node_new(ND_UNARY, tok.loc);
   645→        unary->left = expr;
   646→        unary->op = op;
   647→        unary->is_prefix = 1;
   648→        return unary;
   649→    }
   650→
   651→    if (check(p, TK_INC) || check(p, TK_DEC)) {
   652→        TokenKind op = tok.kind;
   653→        advance(p);
   654→        Node *expr = parse_unary_expr(p);
   655→
   656→        Node *unary = node_new(ND_UNARY, tok.loc);
   657→        unary->left = expr;
   658→        unary->op = op;
   659→        unary->is_prefix = 1;
   660→        return unary;
   661→    }
   662→
   663→    if (check(p, TK_SIZEOF)) {
   664→        advance(p);
   665→        Node *sizeof_node = node_new(ND_SIZEOF_EXPR, tok.loc);
   666→        sizeof_node->left = parse_unary_expr(p);
   667→        return sizeof_node;
   668→    }
   669→
   670→    return parse_postfix_expr(p);
   671→}
   672→
   673→/* 후위 연산자 (++, --, [], ., ->, ()) */
   674→Node *parse_postfix_expr(Parser *p) {
   675→    Node *left = parse_primary_expr(p);
   676→
   677→    while (1) {
   678→        if (check(p, TK_INC) || check(p, TK_DEC)) {
   679→            Token op_tok = *current_token(p);
   680→            TokenKind op = op_tok.kind;
   681→            advance(p);
   682→
   683→            Node *unary = node_new(ND_UNARY, op_tok.loc);
   684→            unary->left = left;
   685→            unary->op = op;
   686→            unary->is_prefix = 0;  /* 후위 */
   687→            left = unary;
   688→        }
   689→        else if (match(p, TK_LBRACKET)) {
   690→            Token idx_tok = *peek_token(p, -1);
   691→            Node *index = node_new(ND_INDEX, idx_tok.loc);
   692→            index->left = left;
   693→            index->right = parse_expr(p);
   694→            consume(p, TK_RBRACKET, "Expected ]");
   695→            left = index;
   696→        }
   697→        else if (match(p, TK_LPAREN)) {
   698→            Token call_tok = *peek_token(p, -1);
   699→            Node *call = node_new(ND_CALL, call_tok.loc);
   700→            call->left = left;
   701→
   702→            /* 인수 파싱 */
   703→            while (!check(p, TK_RPAREN)) {
   704→                Node *arg = parse_assign_expr(p);
   705→                if (arg) node_add_child(call, arg);
   706→
   707→                if (!check(p, TK_RPAREN)) {
   708→                    if (!consume(p, TK_COMMA, "Expected , or ) in function call")) {
   709→                        break;
   710→                    }
   711→                }
   712→            }
   713→            consume(p, TK_RPAREN, "Expected )");
   714→            left = call;
   715→        }
   716→        else if (match(p, TK_DOT)) {
   717→            Token mem_tok = *current_token(p);
   718→            if (!check(p, TK_IDENT)) {
   719→                fprintf(stderr, "Expected identifier after .\n");
   720→                return left;
   721→            }
   722→            Node *member = node_new(ND_MEMBER, mem_tok.loc);
   723→            member->left = left;
   724→            member->name = (char *)malloc(strlen(mem_tok.val.ident) + 1);
   725→            strcpy(member->name, mem_tok.val.ident);
   726→            advance(p);
   727→            left = member;
   728→        }
   729→        else if (match(p, TK_ARROW)) {
   730→            Token mem_tok = *current_token(p);
   731→            if (!check(p, TK_IDENT)) {
   732→                fprintf(stderr, "Expected identifier after ->\n");
   733→                return left;
   734→            }
   735→            Node *arrow = node_new(ND_ARROW, mem_tok.loc);
   736→            arrow->left = left;
   737→            arrow->name = (char *)malloc(strlen(mem_tok.val.ident) + 1);
   738→            strcpy(arrow->name, mem_tok.val.ident);
   739→            advance(p);
   740→            left = arrow;
   741→        }
   742→        else {
   743→            break;
   744→        }
   745→    }
   746→
   747→    return left;
   748→}
   749→
   750→/* 기본 식 (literals, identifiers, parenthesized expressions) */
   751→Node *parse_primary_expr(Parser *p) {
   752→    Token tok = *current_token(p);
   753→
   754→    if (check(p, TK_INT_LIT)) {
   755→        Node *lit = node_new(ND_INT_LIT, tok.loc);
   756→        lit->int_val = tok.val.int_val;
   757→        advance(p);
   758→        return lit;
   759→    }
   760→
   761→    if (check(p, TK_FLOAT_LIT)) {
   762→        Node *lit = node_new(ND_FLOAT_LIT, tok.loc);
   763→        lit->float_val = tok.val.float_val;
   764→        advance(p);
   765→        return lit;
   766→    }
   767→
   768→    if (check(p, TK_CHAR_LIT)) {
   769→        Node *lit = node_new(ND_CHAR_LIT, tok.loc);
   770→        lit->char_val = tok.val.char_val;
   771→        advance(p);
   772→        return lit;
   773→    }
   774→
   775→    if (check(p, TK_STR_LIT)) {
   776→        Node *lit = node_new(ND_STR_LIT, tok.loc);
   777→        lit->str_val = (char *)malloc(strlen(tok.val.str_val) + 1);
   778→        strcpy(lit->str_val, tok.val.str_val);
   779→        advance(p);
   780→        return lit;
   781→    }
   782→
   783→    if (check(p, TK_IDENT)) {
   784→        Node *ident = node_new(ND_IDENT, tok.loc);
   785→        ident->name = (char *)malloc(strlen(tok.val.ident) + 1);
   786→        strcpy(ident->name, tok.val.ident);
   787→        advance(p);
   788→        return ident;
   789→    }
   790→
   791→    if (match(p, TK_LPAREN)) {
   792→        Node *expr = parse_expr(p);
   793→        consume(p, TK_RPAREN, "Expected )");
   794→        return expr;
   795→    }
   796→
   797→    fprintf(stderr, "Unexpected token at line %d\n", tok.loc.line);
   798→    return NULL;
   799→}

