```

**Pseudo-Code Refactoring**:
```c
// Before: 16 error paths × 1-6 cleanup calls each
if (error_condition_1) {
    fprintf(stderr, "Error: ...\n");
    free(source);
    return 1;
}
if (error_condition_2) {
    fprintf(stderr, "Error: ...\n");
    lexer_free(lexer);
    free(source);
    return 1;
}
// ... repeated 9 more times

// After: Centralized cleanup context
typedef struct {
    char *source;
    Lexer *lexer;
    Parser *parser;
    Node *program;
    CirModule *ir;
    AstGen *astgen;
    Sema *sema;
    FILE *fout;
    Codegen *codegen;
} CompilerContext;

#define CLEANUP_AND_RETURN(ctx, msg, code) \
    do { \
        fprintf(stderr, "Error: %s\n", msg); \
        context_free(&ctx); \
        return code; \
    } while(0)

// Usage:
if (!fin) CLEANUP_AND_RETURN(ctx, "Cannot open input", 1);
if (!lexer) CLEANUP_AND_RETURN(ctx, "Lexer init failed", 1);
```

