/* Add to parser.c - near top after includes */

/**
 * Safe string duplication helper
 * Returns heap-allocated copy of string, or NULL on failure/NULL input
 */
static char *dup_string(const char *src) {
    if (!src) return NULL;

    size_t len = strlen(src);
    char *dup = (char *)malloc(len + 1);
    if (!dup) return NULL;  /* Allocation failed */

    strcpy(dup, src);
    return dup;
}

